import unittest
from models import Item
from pricing import order_total


class TestOrderTotal(unittest.TestCase):

    def test_empty_order_totals_zero(self):
        self.assertEqual(order_total([], 0), 0)

    def test_subtotal_calculation_single_item(self):
        items = [Item(sku="item1", qty=2, unit_price_cents=150)]
        self.assertEqual(order_total(items, 0), 300)

    def test_subtotal_calculation_multiple_items(self):
        items = [
            Item(sku="item1", qty=2, unit_price_cents=100),
            Item(sku="item2", qty=3, unit_price_cents=50),
        ]
        self.assertEqual(order_total(items, 0), 350)

    def test_discount_subtraction(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=200)]
        self.assertEqual(order_total(items, 15), 170)

    def test_discount_rounded_down_to_whole_cents(self):
        # 10% of 105 is 10.5 cents; rounded down to 10 cents discount -> total 95 cents
        items = [Item(sku="item1", qty=1, unit_price_cents=105)]
        self.assertEqual(order_total(items, 10), 95)

    def test_discount_percent_zero_edge_value(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=100)]
        self.assertEqual(order_total(items, 0), 100)

    def test_discount_percent_hundred_edge_value(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=100)]
        self.assertEqual(order_total(items, 100), 0)

    def test_unit_price_cents_zero_edge_value(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=0)]
        self.assertEqual(order_total(items, 0), 0)

    def test_qty_one_edge_value(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=100)]
        self.assertEqual(order_total(items, 0), 100)

    def test_discount_percent_less_than_zero_raises_value_error(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=100)]
        with self.assertRaises(ValueError):
            order_total(items, -1)

    def test_discount_percent_greater_than_hundred_raises_value_error(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=100)]
        with self.assertRaises(ValueError):
            order_total(items, 101)

    def test_qty_zero_raises_value_error(self):
        items = [Item(sku="item1", qty=0, unit_price_cents=100)]
        with self.assertRaises(ValueError):
            order_total(items, 0)

    def test_qty_negative_raises_value_error(self):
        items = [Item(sku="item1", qty=-1, unit_price_cents=100)]
        with self.assertRaises(ValueError):
            order_total(items, 0)

    def test_unit_price_cents_negative_raises_value_error(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=-1)]
        with self.assertRaises(ValueError):
            order_total(items, 0)

    def test_duplicate_sku_raises_value_error(self):
        items = [
            Item(sku="shared-sku", qty=1, unit_price_cents=100),
            Item(sku="shared-sku", qty=2, unit_price_cents=200),
        ]
        with self.assertRaises(ValueError):
            order_total(items, 0)


if __name__ == "__main__":
    unittest.main()

import unittest
import fmt
import currency


class TestFormatMoney(unittest.TestCase):
    @staticmethod
    def _get_info(curr):
        try:
            sym = curr.symbol
        except (AttributeError, TypeError):
            try:
                sym = curr['symbol']
            except (TypeError, KeyError):
                sym = curr[0]

        try:
            return sym, curr.decimals
        except (AttributeError, TypeError):
            pass
        try:
            return sym, curr.decimal_places
        except (AttributeError, TypeError):
            pass
        try:
            return sym, curr.places
        except (AttributeError, TypeError):
            pass
        try:
            return sym, curr['decimals']
        except (TypeError, KeyError):
            pass
        try:
            return sym, curr['decimal_places']
        except (TypeError, KeyError):
            pass
        try:
            return sym, curr['places']
        except (TypeError, KeyError):
            pass
        return sym, curr[1]

    def setUp(self):
        self.code_2 = None
        self.sym_2 = None
        self.code_0 = None
        self.sym_0 = None

        for code, info in currency.CURRENCIES.items():
            sym, dec = self._get_info(info)
            if dec == 2 and self.code_2 is None:
                self.code_2 = code
                self.sym_2 = sym
            elif dec == 0 and self.code_0 is None:
                self.code_0 = code
                self.sym_0 = sym

        if self.code_2 is None:
            for code, info in currency.CURRENCIES.items():
                sym, dec = self._get_info(info)
                if dec > 0:
                    self.code_2 = code
                    self.sym_2 = sym
                    break

        self.unknown_code = "ZZZ_UNKNOWN_CURRENCY"
        while self.unknown_code in currency.CURRENCIES:
            self.unknown_code += "_X"

    def test_unknown_currency_raises_value_error(self):
        with self.assertRaises(ValueError):
            fmt.format_money(100, self.unknown_code)

    def test_unknown_currency_zero_raises_value_error(self):
        with self.assertRaises(ValueError):
            fmt.format_money(0, self.unknown_code)

    def test_unknown_currency_negative_raises_value_error(self):
        with self.assertRaises(ValueError):
            fmt.format_money(-100, self.unknown_code)

    def test_zero_amount(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(0, self.code_2), f"{self.sym_2}0.00")

    def test_positive_cents_only(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(1, self.code_2), f"{self.sym_2}0.01")
            self.assertEqual(fmt.format_money(50, self.code_2), f"{self.sym_2}0.50")
            self.assertEqual(fmt.format_money(99, self.code_2), f"{self.sym_2}0.99")

    def test_positive_without_thousands_separator(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(100, self.code_2), f"{self.sym_2}1.00")
            self.assertEqual(fmt.format_money(12345, self.code_2), f"{self.sym_2}123.45")
            self.assertEqual(fmt.format_money(99999, self.code_2), f"{self.sym_2}999.99")

    def test_positive_with_thousands_separator(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(100000, self.code_2), f"{self.sym_2}1,000.00")
            self.assertEqual(fmt.format_money(123450, self.code_2), f"{self.sym_2}1,234.50")
            self.assertEqual(fmt.format_money(123456789, self.code_2), f"{self.sym_2}1,234,567.89")

    def test_negative_small_amount(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(-1, self.code_2), f"-{self.sym_2}0.01")
            self.assertEqual(fmt.format_money(-50, self.code_2), f"-{self.sym_2}0.50")

    def test_negative_amount_minus_before_symbol(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(-123450, self.code_2), f"-{self.sym_2}1,234.50")
            self.assertEqual(fmt.format_money(-100, self.code_2), f"-{self.sym_2}1.00")

    def test_negative_large_amount_with_grouping(self):
        if self.code_2 is not None:
            self.assertEqual(fmt.format_money(-123456789, self.code_2), f"-{self.sym_2}1,234,567.89")

    def test_zero_decimals_zero_amount(self):
        if self.code_0 is not None:
            self.assertEqual(fmt.format_money(0, self.code_0), f"{self.sym_0}0")

    def test_zero_decimals_positive(self):
        if self.code_0 is not None:
            self.assertEqual(fmt.format_money(5, self.code_0), f"{self.sym_0}5")
            self.assertEqual(fmt.format_money(999, self.code_0), f"{self.sym_0}999")

    def test_zero_decimals_thousands_grouping(self):
        if self.code_0 is not None:
            self.assertEqual(fmt.format_money(1000, self.code_0), f"{self.sym_0}1,000")
            self.assertEqual(fmt.format_money(1234567, self.code_0), f"{self.sym_0}1,234,567")

    def test_zero_decimals_negative(self):
        if self.code_0 is not None:
            self.assertEqual(fmt.format_money(-1, self.code_0), f"-{self.sym_0}1")
            self.assertEqual(fmt.format_money(-1000, self.code_0), f"-{self.sym_0}1,000")
            self.assertEqual(fmt.format_money(-1234567, self.code_0), f"-{self.sym_0}1,234,567")

    def test_all_currencies_use_correct_symbol(self):
        for code, info in currency.CURRENCIES.items():
            sym, _ = self._get_info(info)
            self.assertTrue(fmt.format_money(0, code).startswith(sym))


if __name__ == "__main__":
    unittest.main()

