class TestOrderTotal(unittest.TestCase):

    def test_empty_order_totals_zero(self):
        self.assertEqual(order_total([], 0), 0)

    def test_subtotal_calculation_single_item(self):
        items = [Item(sku="item1", qty=2, unit_price_cents=150)]
        self.assertEqual(order_total(items, 0), 300)

    def test_subtotal_calculation_multiple_items(self):
        items = [
            Item(sku="item1", qty=2, unit_price_cents=100),
            Item(sku="item2", qty=3, unit_price_cents=50),
        ]
        self.assertEqual(order_total(items, 0), 350)

    def test_discount_subtraction(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=200)]
        self.assertEqual(order_total(items, 15), 170)

    def test_discount_rounded_down_to_whole_cents(self):
        # 10% of 105 is 10.5 cents; rounded down to 10 cents discount -> total 95 cents
        items = [Item(sku="item1", qty=1, unit_price_cents=105)]
        self.assertEqual(order_total(items, 10), 95)

    def test_discount_percent_zero_edge_value(self):
        items = [Item(sku="item1", qty=1, unit_price_cents=100)]
        self.assertEqual(order_total(items, 0), 100)

